var s=`0975-japchae`;var t=`world-0975`;var a=`KR`;var n=`east-asia`;var o=4;var r=30;var g={en:`Japchae`,ua:`Чапче`};var l={en:`Japchae is a South Korea dish made with sweet potato noodles, beef sirloin, shiitake mushroom, carrot. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Чапче, страва кухні країни Південна Корея. Основні складники: локшина з батату, яловичий сирлойн, шиїтаке, морква. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var h=[{en:`Cook the listed ingredients in simmering water for about 9 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 9 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:9,i:[[`sweet-potato-noodles`,370,`g`],[`water`,1100,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 11 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 11 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:11,i:[[`beef-sirloin`,250,`g`],[`shiitake-mushroom`,160,`g`],[`carrot`,190,`g`],[`yellow-onion`,160,`g`],[`spinach`,200,`g`],[`canola-oil`,40,`ml`]]},{en:`Fold in the dressing ingredients, season to taste and serve, or chill briefly as appropriate.`,ua:`Обережно змішайте із заправкою, приправте до смаку й подавайте або трохи охолодіть за потреби.`,t:[`tossing`,`seasoning`],m:7,i:[[`light-soy-sauce`,65,`ml`],[`white-granulated-sugar`,28,`g`],[`toasted-sesame-oil`,35,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`white-sesame-seeds`,22,`g`]]}];var d={slug:s,id:t,country:`KR`,region:n,servings:4,minutes:30,title:g,text:l,steps:h};export{a as country,d as default,t as id,r as minutes,n as region,o as servings,s as slug,h as steps,l as text,g as title};